// ============================================================
//  Trainer Booking — CrossGYM. Stage 3.
//  Сторінка статична (без Sheets) — миттєвий перший показ.
//  Розклад/капасіті підвантажуються окремим запитом у фоні.
// ============================================================
const DATA = {
  clubs: [
    { id: "c2", name: "CrossGYM — 95 квартал", addr: "пр. Гагаріна, 4а (Плаза)", accent: "#4CAF50" },
    { id: "c3", name: "CrossGYM — Вечірній", addr: "б-р Вечірній, 18а", accent: "#E8402A" }
  ]
};
const WEEKDAY_NAMES = ['нд', 'пн', 'вт', 'ср', 'чт', 'пт', 'сб'];

const TEMPLATE = `<!DOCTYPE html>
<html>
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1, viewport-fit=cover">
<title>Запис на тренування</title>
<script src="https://telegram.org/js/telegram-web-app.js"></script>
<style>
  :root {
    --page:    var(--tg-theme-secondary-bg-color, #efeff4);
    --card:    var(--tg-theme-bg-color, #ffffff);
    --text:    var(--tg-theme-text-color, #000000);
    --muted:   var(--tg-theme-hint-color, #8a8a8e);
    --accent:  var(--tg-theme-button-color, #2481cc);
    --onaccent:var(--tg-theme-button-text-color, #ffffff);
    --sep:     rgba(60,60,67,.18);
    --header:  var(--tg-theme-section-header-text-color, #8a8a8e);
    --radius: 12px;
  }
  html.dark { --card: rgba(255,255,255,.07); --sep: rgba(255,255,255,.12); }
  * { box-sizing: border-box; -webkit-tap-highlight-color: transparent; }
  html, body { height: 100%; }
  body {
    margin: 0; padding: 0 0 calc(24px + env(safe-area-inset-bottom));
    min-height: 100vh;
    min-height: var(--tg-vh, 100vh);
    font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", system-ui, sans-serif;
    background: var(--page); color: var(--text); font-size: 17px; line-height: 1.35;
    -webkit-font-smoothing: antialiased;
  }
  .shead { font-size: 13px; font-weight: 400; letter-spacing: .02em; color: var(--header); text-transform: uppercase; padding: 20px 16px 7px; }
  .group { background: var(--card); border-radius: var(--radius); margin: 0 16px; overflow: hidden; }
  .row { display: flex; align-items: center; gap: 12px; width: 100%; text-align: left; padding: 11px 16px; min-height: 46px; background: none; border: 0; cursor: pointer; position: relative; }
  .row + .row::before { content: ''; position: absolute; left: 16px; right: 0; top: 0; height: 1px; transform: scaleY(.5); background: var(--sep); }
  .row:active { background: var(--sep); }
  .row[disabled] { opacity: .4; cursor: default; }
  .row[disabled]:active { background: none; }
  .row.static { cursor: default; }
  .dot { width: 10px; height: 10px; border-radius: 50%; flex-shrink: 0; }
  .grow { flex: 1; min-width: 0; }
  .title { font-size: 17px; }
  .sub { font-size: 13px; color: var(--muted); margin-top: 1px; }
  .chev { color: var(--muted); font-size: 20px; }
  .primary { background: var(--accent); color: var(--onaccent); border: 0; border-radius: var(--radius);
    width: calc(100% - 32px); margin: 20px 16px; padding: 14px; font-size: 17px; font-weight: 600; cursor: pointer; }
  .primary[disabled] { opacity: .5; cursor: default; }
  .backbtn { display: block; background: none; border: 0; color: var(--accent); font-size: 17px;
    padding: 16px 16px 0; cursor: pointer; }
  .backbtn:active { opacity: .5; }
  .statusmsg { padding: 8px 16px 0; font-size: 14px; text-align: center; color: var(--muted); min-height: 20px; }
  .statusmsg.ok { color: #34a853; font-weight: 600; }
  .statusmsg.error { color: #e8402a; }
  .cancelbtn { background: none; border: 1px solid #e8402a; color: #e8402a; border-radius: 8px;
    padding: 6px 12px; font-size: 14px; cursor: pointer; white-space: nowrap; }
  .cancelbtn[disabled] { opacity: .5; }
</style>
</head>
<body>
  <div id="app"></div>

<script>
  const tg = window.Telegram && window.Telegram.WebApp;
  function applyViewportHeight() {
    if (tg && tg.viewportStableHeight) {
      document.documentElement.style.setProperty('--tg-vh', tg.viewportStableHeight + 'px');
    }
  }
  if (tg) {
    tg.ready();
    tg.expand();
    applyViewportHeight();
    tg.onEvent('viewportChanged', applyViewportHeight);
  }
  if (tg && tg.colorScheme === 'dark') document.documentElement.classList.add('dark');

  const CLUBS = __CLUBS__;
  const WD = __WEEKDAYS__;
  const API_BOOK = '__API_BOOK__';
  const API_MINE = '__API_MINE__';
  const API_CANCEL = '__API_CANCEL__';
  const API_SCHEDULE = '__API_SCHEDULE__';
  const API_ADMIN = '__API_ADMIN__';
  // Лише для показу пункту меню — реальний доступ перевіряється на сервері
  // за підписом initData, це не про безпеку.
  const ADMIN_TELEGRAM_ID = '7656322828';
  const IS_ADMIN = !!(tg && tg.initDataUnsafe && tg.initDataUnsafe.user
    && String(tg.initDataUnsafe.user.id) === ADMIN_TELEGRAM_ID);

  const app = document.getElementById('app');
  let currentClub = null;

  // Розклад підвантажується у фоні одразу при відкритті — щоб перший
  // екран (список залів) показувався миттєво, без очікування Sheets.
  let SESSIONS = null;
  const schedulePromise = fetch(API_SCHEDULE, { method: 'POST' })
    .then(r => r.json())
    .then(d => { SESSIONS = d.sessions || []; })
    .catch(() => { SESSIONS = []; });

  function showBack(fn) {
    if (!tg || !tg.BackButton) return;
    try {
      if (showBack._last) tg.BackButton.offClick(showBack._last);
      if (fn) { tg.BackButton.show(); tg.BackButton.onClick(fn); showBack._last = fn; }
      else { tg.BackButton.hide(); showBack._last = null; }
    } catch (e) {}
  }

  function renderClubs() {
    currentClub = null;
    showBack(null);
    app.innerHTML = \`
      <div class="group" style="margin-top:16px">
        <button class="row" onclick="openMyBookings()">
          <span class="grow"><div class="title">Мої записи</div></span>
          <span class="chev">›</span>
        </button>
        \${IS_ADMIN ? \`<button class="row" onclick="openAdmin()">
          <span class="grow"><div class="title">Хто записався</div></span>
          <span class="chev">›</span>
        </button>\` : ''}
      </div>
      <div class="shead">Оберіть зал</div><div class="group" id="clubs"></div>
    \`;
    document.getElementById('clubs').innerHTML = CLUBS.map(c => \`
      <button class="row" onclick="openClub('\${c.id}')">
        <span class="dot" style="background:\${c.accent}"></span>
        <span class="grow"><div class="title">\${c.name}</div><div class="sub">\${c.addr}</div></span>
        <span class="chev">›</span>
      </button>\`).join('');
  }

  async function openAdmin() {
    showBack(renderClubs);
    app.innerHTML = '<button class="backbtn" onclick="renderClubs()">‹ Зали</button>'
      + '<div class="shead">Хто записався</div><div class="group" id="admin"><div class="row static"><span class="grow"><div class="sub">Завантаження…</div></span></div></div>';
    const box = document.getElementById('admin');
    const initData = tg ? tg.initData : '';
    try {
      const res = await fetch(API_ADMIN, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ initData })
      });
      const data = await res.json();
      const list = data.sessions || [];
      if (!list.length) {
        box.innerHTML = '<div class="row static"><span class="grow"><div class="sub">Немає найближчих занять</div></span></div>';
        return;
      }
      box.innerHTML = list.map(s => \`
        <div class="row static">
          <span class="grow">
            <div class="title">\${s.clubName} · \${WD[s.weekday]}, \${s.date.slice(8,10)}.\${s.date.slice(5,7)} \${s.time}</div>
            <div class="sub">\${s.roster.length} з \${s.capacity}\${s.roster.length ? ': ' + s.roster.join(', ') : ' — поки нікого'}</div>
          </span>
        </div>\`).join('');
    } catch (e) {
      box.innerHTML = '<div class="row static"><span class="grow"><div class="sub">Помилка мережі, спробуйте ще раз</div></span></div>';
    }
  }

  async function openMyBookings() {
    showBack(renderClubs);
    app.innerHTML = '<button class="backbtn" onclick="renderClubs()">‹ Зали</button>'
      + '<div class="shead">Мої записи</div><div class="group" id="mine"><div class="row static"><span class="grow"><div class="sub">Завантаження…</div></span></div></div>';
    const box = document.getElementById('mine');
    const initData = tg ? tg.initData : '';
    try {
      const res = await fetch(API_MINE, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ initData })
      });
      const data = await res.json();
      const list = (data.bookings || []).filter(b => !b.past);
      if (!list.length) {
        box.innerHTML = '<div class="row static"><span class="grow"><div class="sub">У вас поки немає записів</div></span></div>';
        return;
      }
      box.innerHTML = list.map(b => \`
        <div class="row static">
          <span class="grow">
            <div class="title">\${b.clubName}</div>
            <div class="sub">\${WD[b.weekday]}, \${b.date.slice(8,10)}.\${b.date.slice(5,7)} · \${b.time}</div>
          </span>
          \${b.canCancel
            ? '<button class="cancelbtn" onclick="cancelBooking(\\'' + b.booking_id + '\\', this)">Скасувати</button>'
            : '<span class="sub">менше 3 год</span>'}
        </div>\`).join('');
    } catch (e) {
      box.innerHTML = '<div class="row static"><span class="grow"><div class="sub">Помилка мережі, спробуйте ще раз</div></span></div>';
    }
  }

  async function cancelBooking(bookingId, btn) {
    btn.disabled = true;
    btn.textContent = '…';
    const initData = tg ? tg.initData : '';
    try {
      const res = await fetch(API_CANCEL, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ initData, bookingId })
      });
      const data = await res.json();
      if (data.ok) {
        schedulePromise.then(() => {});
        fetch(API_SCHEDULE, { method: 'POST' }).then(r => r.json()).then(d => { SESSIONS = d.sessions || []; }).catch(() => {});
        openMyBookings();
      } else {
        btn.disabled = false;
        btn.textContent = 'Скасувати';
        if (tg && tg.HapticFeedback) { try { tg.HapticFeedback.notificationOccurred('error'); } catch (e) {} }
        alert(data.error || 'Не вдалося скасувати');
      }
    } catch (e) {
      btn.disabled = false;
      btn.textContent = 'Скасувати';
      alert('Помилка мережі, спробуйте ще раз');
    }
  }

  async function openClub(id) {
    currentClub = id;
    showBack(renderClubs);
    const club = CLUBS.find(c => c.id === id);
    app.innerHTML = '<button class="backbtn" onclick="renderClubs()">‹ Зали</button>'
      + '<div class="shead">' + club.name + '</div><div class="group" id="sess"><div class="row static"><span class="grow"><div class="sub">Завантаження…</div></span></div></div>';
    if (SESSIONS === null) await schedulePromise;
    if (currentClub !== id) return;
    renderSessions(id);
  }

  function renderSessions(id) {
    const box = document.getElementById('sess');
    if (!box) return;
    const list = (SESSIONS || []).filter(s => s.club === id);
    if (!list.length) {
      box.innerHTML = '<div class="row static"><span class="grow"><div class="sub">Найближчих занять немає</div></span></div>';
      return;
    }
    box.innerHTML = list.map((s, i) => \`
      <button class="row" \${s.free <= 0 ? 'disabled' : ''} onclick="openSession(\${i})" data-i="\${i}">
        <span class="grow">
          <div class="title">\${WD[s.weekday]}, \${s.date.slice(8,10)}.\${s.date.slice(5,7)} · \${s.time}</div>
          <div class="sub">\${s.free > 0 ? 'Вільно ' + s.free + ' з ' + s.capacity : 'Місць немає'}</div>
        </span>
      </button>\`).join('');
    window.__list = list;
  }

  function openSession(i) {
    const s = window.__list[i];
    const club = CLUBS.find(c => c.id === s.club);
    showBack(() => openClub(s.club));
    app.innerHTML = \`
      <button class="backbtn" onclick="openClub('\${s.club}')">‹ Назад</button>
      <div class="shead">Підтвердження</div>
      <div class="group">
        <div class="row static"><span class="grow"><div class="title">\${club.name}</div><div class="sub">\${club.addr}</div></span></div>
        <div class="row static"><span class="grow"><div class="title">\${WD[s.weekday]}, \${s.date.slice(8,10)}.\${s.date.slice(5,7)} о \${s.time}</div><div class="sub">Вільно \${s.free} з \${s.capacity}</div></span></div>
      </div>
      <button class="primary" id="confirmBtn">Записатися</button>
      <div class="statusmsg" id="status"></div>
    \`;
    document.getElementById('confirmBtn').onclick = () => book(s);
  }

  async function book(s) {
    const btn = document.getElementById('confirmBtn');
    const status = document.getElementById('status');
    btn.disabled = true;
    btn.textContent = 'Записую…';
    status.className = 'statusmsg';
    status.textContent = '';
    const initData = tg ? tg.initData : '';
    try {
      const res = await fetch(API_BOOK, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ initData, club: s.club, weekday: s.weekday, time: s.time, date: s.date })
      });
      const data = await res.json();
      if (data.ok) {
        status.className = 'statusmsg ok';
        status.textContent = '✓ Записано!';
        try { tg && tg.HapticFeedback && tg.HapticFeedback.notificationOccurred('success'); } catch (e) {}
        fetch(API_SCHEDULE, { method: 'POST' }).then(r => r.json()).then(d => { SESSIONS = d.sessions || []; }).catch(() => {});
        setTimeout(() => openClub(s.club), 900);
      } else {
        status.className = 'statusmsg error';
        status.textContent = data.error || 'Не вдалося записатися';
        btn.disabled = false;
        btn.textContent = 'Записатися';
      }
    } catch (e) {
      status.className = 'statusmsg error';
      status.textContent = 'Помилка мережі, спробуйте ще раз';
      btn.disabled = false;
      btn.textContent = 'Записатися';
    }
  }

  renderClubs();
</script>
</body>
</html>
`;

const html = TEMPLATE
  .replace('__CLUBS__', JSON.stringify(DATA.clubs))
  .replace('__WEEKDAYS__', JSON.stringify(WEEKDAY_NAMES))
  .replace('__API_BOOK__', 'https://n8n.morthain.com/webhook/trainer-booking-book')
  .replace('__API_MINE__', 'https://n8n.morthain.com/webhook/trainer-booking-mine')
  .replace('__API_CANCEL__', 'https://n8n.morthain.com/webhook/trainer-booking-cancel')
  .replace('__API_SCHEDULE__', 'https://n8n.morthain.com/webhook/trainer-booking-schedule')
  .replace('__API_ADMIN__', 'https://n8n.morthain.com/webhook/trainer-booking-admin');

return [{ json: { html } }];

// ---- SHA-256 і HMAC вручну (n8n забороняє require('crypto')) ----
// Реалізація перенесена з crossgym-miniapp, звірена з еталоном node:crypto на 375 тестах.
const K256 = [
  0x428a2f98,0x71374491,0xb5c0fbcf,0xe9b5dba5,0x3956c25b,0x59f111f1,0x923f82a4,0xab1c5ed5,
  0xd807aa98,0x12835b01,0x243185be,0x550c7dc3,0x72be5d74,0x80deb1fe,0x9bdc06a7,0xc19bf174,
  0xe49b69c1,0xefbe4786,0x0fc19dc6,0x240ca1cc,0x2de92c6f,0x4a7484aa,0x5cb0a9dc,0x76f988da,
  0x983e5152,0xa831c66d,0xb00327c8,0xbf597fc7,0xc6e00bf3,0xd5a79147,0x06ca6351,0x14292967,
  0x27b70a85,0x2e1b2138,0x4d2c6dfc,0x53380d13,0x650a7354,0x766a0abb,0x81c2c92e,0x92722c85,
  0xa2bfe8a1,0xa81a664b,0xc24b8b70,0xc76c51a3,0xd192e819,0xd6990624,0xf40e3585,0x106aa070,
  0x19a4c116,0x1e376c08,0x2748774c,0x34b0bcb5,0x391c0cb3,0x4ed8aa4a,0x5b9cca4f,0x682e6ff3,
  0x748f82ee,0x78a5636f,0x84c87814,0x8cc70208,0x90befffa,0xa4506ceb,0xbef9a3f7,0xc67178f2
];
function sha256(msg) {
  const H = [0x6a09e667,0xbb67ae85,0x3c6ef372,0xa54ff53a,0x510e527f,0x9b05688c,0x1f83d9ab,0x5be0cd19];
  const bitLen = msg.length * 8;
  const buf = new Uint8Array(((msg.length + 9 + 63) >> 6) << 6);
  buf.set(msg); buf[msg.length] = 0x80;
  const dv = new DataView(buf.buffer);
  dv.setUint32(buf.length - 8, Math.floor(bitLen / 0x100000000));
  dv.setUint32(buf.length - 4, bitLen >>> 0);
  const w = new Uint32Array(64);
  const rotr = (x, n) => (x >>> n) | (x << (32 - n));
  for (let off = 0; off < buf.length; off += 64) {
    for (let i = 0; i < 16; i++) w[i] = dv.getUint32(off + i * 4);
    for (let i = 16; i < 64; i++) {
      const s0 = rotr(w[i-15],7) ^ rotr(w[i-15],18) ^ (w[i-15] >>> 3);
      const s1 = rotr(w[i-2],17) ^ rotr(w[i-2],19) ^ (w[i-2] >>> 10);
      w[i] = (w[i-16] + s0 + w[i-7] + s1) >>> 0;
    }
    let a=H[0],b=H[1],c=H[2],d=H[3],e=H[4],f=H[5],g=H[6],h=H[7];
    for (let i = 0; i < 64; i++) {
      const S1 = rotr(e,6) ^ rotr(e,11) ^ rotr(e,25);
      const ch = (e & f) ^ (~e & g);
      const t1 = (h + S1 + ch + K256[i] + w[i]) >>> 0;
      const S0 = rotr(a,2) ^ rotr(a,13) ^ rotr(a,22);
      const maj = (a & b) ^ (a & c) ^ (b & c);
      const t2 = (S0 + maj) >>> 0;
      h=g; g=f; f=e; e=(d+t1)>>>0; d=c; c=b; b=a; a=(t1+t2)>>>0;
    }
    H[0]=(H[0]+a)>>>0; H[1]=(H[1]+b)>>>0; H[2]=(H[2]+c)>>>0; H[3]=(H[3]+d)>>>0;
    H[4]=(H[4]+e)>>>0; H[5]=(H[5]+f)>>>0; H[6]=(H[6]+g)>>>0; H[7]=(H[7]+h)>>>0;
  }
  const out = new Uint8Array(32);
  const odv = new DataView(out.buffer);
  for (let i = 0; i < 8; i++) odv.setUint32(i * 4, H[i]);
  return out;
}
function concatBytes(a, b) { const r = new Uint8Array(a.length + b.length); r.set(a); r.set(b, a.length); return r; }
function hmacSha256(key, msg) {
  const B = 64;
  const k = key.length > B ? sha256(key) : key;
  const pad = new Uint8Array(B); pad.set(k);
  const ipad = new Uint8Array(B), opad = new Uint8Array(B);
  for (let i = 0; i < B; i++) { ipad[i] = pad[i] ^ 0x36; opad[i] = pad[i] ^ 0x5c; }
  return sha256(concatBytes(opad, sha256(concatBytes(ipad, msg))));
}
function utf8(str) {
  const out = [];
  for (let i = 0; i < str.length; i++) {
    let c = str.charCodeAt(i);
    if (c < 0x80) out.push(c);
    else if (c < 0x800) out.push(0xc0 | (c >> 6), 0x80 | (c & 63));
    else if (c >= 0xd800 && c <= 0xdbff && i + 1 < str.length) {
      const c2 = str.charCodeAt(i + 1);
      const cp = 0x10000 + ((c - 0xd800) << 10) + (c2 - 0xdc00);
      out.push(0xf0 | (cp >> 18), 0x80 | ((cp >> 12) & 63), 0x80 | ((cp >> 6) & 63), 0x80 | (cp & 63));
      i++;
    } else out.push(0xe0 | (c >> 12), 0x80 | ((c >> 6) & 63), 0x80 | (c & 63));
  }
  return new Uint8Array(out);
}
function toHex(bytes) { let s = ''; for (let i = 0; i < bytes.length; i++) s += bytes[i].toString(16).padStart(2, '0'); return s; }
function equalConstTime(a, b) {
  if (a.length !== b.length) return false;
  let diff = 0;
  for (let i = 0; i < a.length; i++) diff |= a.charCodeAt(i) ^ b.charCodeAt(i);
  return diff === 0;
}

// ============================================================
//  Перевірка підпису Telegram + валідація слота проти серверних даних.
//  Ліміт місць і сам факт існування слота беремо ЗІ СВОЄЇ таблиці,
//  а не з тіла запиту — клієнтський JS можна підмінити.
// ============================================================
const SLOTS = [
  { club: "c2", weekday: 1, time: "18:00", capacity: 30 },
  { club: "c2", weekday: 3, time: "18:00", capacity: 30 },
  { club: "c2", weekday: 5, time: "18:00", capacity: 30 },
  { club: "c3", weekday: 2, time: "18:00", capacity: 30 },
  { club: "c3", weekday: 4, time: "18:00", capacity: 30 },
  { club: "c3", weekday: 6, time: "10:00", capacity: 30 }
];

const TELEGRAM_BOT_TOKEN = $env.TELEGRAM_BOT_TOKEN;
if (!TELEGRAM_BOT_TOKEN) throw new Error('Немає змінної TELEGRAM_BOT_TOKEN в оточенні n8n');

