const ADMIN_TELEGRAM_ID = '7656322828';

const TELEGRAM_BOT_TOKEN = $env.TELEGRAM_BOT_TOKEN;
if (!TELEGRAM_BOT_TOKEN) throw new Error('Немає змінної TELEGRAM_BOT_TOKEN в оточенні n8n');

const body = $json.body || {};
const initData = body.initData || '';
if (!initData) throw new Error('initData порожній — запит не з Telegram');

const params = parseInitData(initData);
const hash = params.get('hash') || '';
params.delete('hash');
const dataCheckString = Array.from(params.entries())
  .sort((a, b) => (a[0] < b[0] ? -1 : a[0] > b[0] ? 1 : 0))
  .map(([k, v]) => k + '=' + v)
  .join('\n');

const secret = hmacSha256(utf8('WebAppData'), utf8(TELEGRAM_BOT_TOKEN));
const calc = toHex(hmacSha256(secret, utf8(dataCheckString)));
if (!equalConstTime(calc, hash)) throw new Error('Підпис не зійшовся — запит підроблено');

const authDate = Number(params.get('auth_date') || 0);
if (Math.floor(Date.now() / 1000) - authDate > 86400) {
  throw new Error('Підпис протермінований, перевідкрий застосунок');
}

const user = JSON.parse(params.get('user') || '{}');
if (!user.id) throw new Error('Немає user.id в initData');

if (String(user.id) !== ADMIN_TELEGRAM_ID) {
  throw new Error('Немає доступу');
}

return [{ json: { telegramId: user.id } }];

